import React, { useState, useEffect, useRef } from 'react';
import { fetchApplicant } from './api/apiClient';
import './index.css';

const ApplicantDashboard = ({ applicantId, token }) => {
  const [applicant, setApplicant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [progress, setProgress] = useState(0);
  const [doneMessage, setDoneMessage] = useState('');
  const pollTimer = useRef(null);
  const progressTimer = useRef(null);

  useEffect(() => {
    let cancelled = false;
    const loadApplicant = async () => {
      if (!applicant) setLoading(true);
      setError('');
      try {
        const res = await fetchApplicant(applicantId, token);
        if (cancelled) return;
        setApplicant(res.data);
        // If still processing, poll again in 3s
        const status = (res.data?.status || '').toString();
        if (status === 'submitted' || status === 'processing') {
          pollTimer.current = setTimeout(loadApplicant, 3000);
          // Start or continue simulated progress while processing
          if (!progressTimer.current) {
            progressTimer.current = setInterval(() => {
              setProgress((p) => {
                // Ease towards 90% while processing
                if (p < 90) {
                  const increment = Math.max(1, Math.round((90 - p) * 0.1));
                  return Math.min(90, p + increment);
                }
                return p;
              });
            }, 800);
          }
        } else if (status === 'processed') {
          // Completed: fill progress to 100, show thank-you, then redirect
          setProgress(100);
          setDoneMessage('Thank you for submitting your resume. Your information has been received.');
          // Redirect after a short delay
          setTimeout(() => {
            window.location.href = '/';
          }, 2500);
          if (progressTimer.current) {
            clearInterval(progressTimer.current);
            progressTimer.current = null;
          }
        }
      } catch (err) {
        if (!cancelled) setError('Failed to load applicant data.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    loadApplicant();
    return () => {
      cancelled = true;
      if (pollTimer.current) clearTimeout(pollTimer.current);
      if (progressTimer.current) clearInterval(progressTimer.current);
    };
  }, [applicantId, token]);

  // Show progress UI while loading or processing
  const status = (applicant?.status || '').toString();
  if (loading || status === 'submitted' || status === 'processing') {
    return (
      <div>
        <div className="hero">
          <div>
            <div className="chip">Applicant</div>
            <div className="hero-title">Processing your application</div>
            <div className="hero-copy">We’re analyzing your resume and profile. This usually takes a moment.</div>
          </div>
        </div>
        <div className="card">
          <div className="progress" style={{ marginTop: 6 }}>
            <div className="bar" style={{ width: `${progress}%` }} />
          </div>
          <p className="muted" style={{ marginTop: 8 }}>{progress}%</p>
          {doneMessage && <p className="success" style={{ marginTop: 12 }}>{doneMessage}</p>}
        </div>
      </div>
    );
  }
  if (error) return <div style={{ color: 'red' }}>{error}</div>;
  if (!applicant) return <div>No applicant data found.</div>;

  // When loaded and not processing, do NOT show insights; show thank you and send home
  return (
    <div>
      <div className="hero">
        <div>
          <div className="chip">Applicant</div>
          <div className="hero-title">Thank you for submitting</div>
          <div className="hero-copy">We’ve received your information. You’ll be redirected to the home page shortly.</div>
        </div>
      </div>
      <div className="card">
        <p className="muted">If you’re not redirected automatically, you can return to the home page manually.</p>
      </div>
    </div>
  );
};

export default ApplicantDashboard;
